python - <<'PY'
from datetime import datetime, timedelta
from decimal import Decimal
from fractions import Fraction
from itertools import product
from more_itertools import interleave_evenly, sliced, numeric_range

for inputs in ([], (), [[]], [[], []], [[], [], []]):
    assert list(interleave_evenly(inputs)) == []
    assert list(interleave_evenly(inputs, lengths=[0] * len(inputs))) == []
for inputs in ([[], [1, 2]], [[1, 2], []], [[], [1], [], [2, 3]]):
    result = list(interleave_evenly(inputs))
    assert sorted(result) == sorted(x for seq in inputs for x in seq)
for strict, seq in product((False, True), ('', 'abcdef', [], [1, 2])):
    for n in (-1, -2, -100):
        try:
            sliced(seq, n, strict=strict)
        except ValueError:
            pass
        else:
            raise AssertionError((seq, n, strict))
    assert list(sliced(seq, 0, strict=strict)) == []

for start, stop, step in product(range(-5, 6), range(-5, 6), (-3, -1, 1, 3)):
    r = numeric_range(start, stop, step)
    assert list(reversed(r)) == list(range(start, stop, step))[::-1]
for typ in (float, Decimal, Fraction):
    for start, stop, step in product(('-1.2', '0', '0.1', '1.2'), repeat=3):
        if typ(step) == 0:
            continue
        r = numeric_range(typ(start), typ(stop), typ(step))
        assert list(reversed(r)) == list(r)[::-1], r
for step in (timedelta(days=1), timedelta(days=-1)):
    for a, b in product((1, 3), repeat=2):
        r = numeric_range(datetime(2020, 1, a), datetime(2020, 1, b), step)
        assert list(reversed(r)) == list(r)[::-1]
print('All targeted regression checks passed.')
